// Confirmation and immutable retention amendments. No service calls.
function parseChange(text){
 if(typeof text!=='string')return null;
 const input=text.trim();if(!/^\/?(?:extend|keep)(?:@[A-Za-z0-9_]+)?(?:\s|$)/i.test(input))return null;
 let m=input.match(/^\/?extend(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+([0-9]+)\s+days?$/i);
 if(m&&Number(m[2])>=1&&Number(m[2])<=3650)return {operation:'extend',query:m[1].trim(),days:Number(m[2])};
 m=input.match(/^\/?keep(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+permanently$/i);
 if(m)return {operation:'permanent',query:m[1].trim()};
 return {error:'Use extend <title> 7 days (1–3650 whole days), or keep <title> permanently.'};
}
function prepareChange(actor,rows){
 if(!['discord','telegram'].includes(actor.source)||typeof actor.userId!=='string'||!/^\d+$/.test(actor.userId))throw Error('Invalid actor');
 const parsed=parseChange(actor.text);if(!parsed||parsed.error)return {notice:parsed?.error||'Not a retention command.'};
 const matches=rows.filter(r=>r.source===actor.source&&r.userId===actor.userId&&r.userId!=='1'&&r.state==='registered'&&r.requestKey&&['movie','tv'].includes(r.mediaType)&&/^\d+$/.test(String(r.mediaId))&&String(r.title).toLowerCase().includes(parsed.query.toLowerCase()));
 const keys=new Set(matches.map(r=>r.mediaType+':'+r.mediaId));
 if(!matches.length)return {notice:'No requests of yours match that title on this platform.'};
 if(keys.size!==1)return {notice:'Several matches. Please use a more specific title:\n'+[...new Set(matches.map(r=>r.title))].slice(0,8).map(t=>'• '+String(t).slice(0,100)).join('\n')};
 const r=matches[0];return {change:{...parsed,source:actor.source,userId:actor.userId,requestKeys:[...new Set(matches.map(r=>r.requestKey))],mediaType:r.mediaType,mediaId:String(r.mediaId),title:String(r.title).slice(0,150)}};
}
function planChange(change,requests,decisions,records,{pendingId,now}){
 if(!['extend','permanent'].includes(change.operation)||!Array.isArray(change.requestKeys)||!change.requestKeys.length||!/^\d+$/.test(String(pendingId))||!Number.isFinite(now))throw Error('Invalid amendment');
 if(change.operation==='extend'&&(!Number.isInteger(change.days)||change.days<1||change.days>3650))throw Error('Invalid duration');
 const selected=change.requestKeys.map(key=>requests.find(r=>r.requestKey===key));
 if(selected.some(r=>!r||r.state!=='registered'||r.mediaType!==change.mediaType||String(r.mediaId)!==change.mediaId||r.source!==change.source||r.userId!==change.userId))throw Error('Request ownership changed');
 const existing=records.filter(r=>r.key==='change:'+pendingId);
 if(existing.length>1)throw Error('Duplicate amendment');
 if(existing.length){const e=JSON.parse(existing[0].payloadJson);if(e.source!==change.source||e.userId!==change.userId||e.operation!==change.operation||e.mediaId!==change.mediaId||e.mediaType!==change.mediaType)throw Error('Amendment collision');return e;}
 const result={version:1,pendingId:String(pendingId),operation:change.operation,source:change.source,userId:change.userId,requestKeys:change.requestKeys,mediaType:change.mediaType,mediaId:change.mediaId,title:change.title,createdAt:new Date(now).toISOString(),files:[]};
 if(change.operation==='permanent')return result;
 const ids=new Set(selected.flatMap(r=>JSON.parse(r.episodeIdsJson||'[]').map(String)));
 for(const row of records)if(selected.some(r=>row.key==='request:'+r.requestKey))for(const id of JSON.parse(row.payloadJson).episodeIds||[])ids.add(String(id));
 for(const d of decisions){
  if(change.mediaType==='tv'&&!(d.episodeIds||[]).some(id=>ids.has(String(id))))continue;
  if(d.state!=='tracked'||d.identityProtected||!d.expiresAt||!Number.isFinite(Date.parse(d.expiresAt))||!Number.isFinite(Date.parse(d.importedAt))||!Number.isSafeInteger(d.fileId)||typeof d.path!=='string')continue;
  const minimumExpiry=new Date(Math.max(now,Date.parse(d.expiresAt))+change.days*86400000).toISOString();
  result.files.push({fileId:d.fileId,path:d.path,importedAt:d.importedAt,minimumExpiry});
 }
 if(!result.files.length)return {notice:'No imported files with a timed expiry need extending. Files already protected stay protected; upcoming episodes keep their existing retention.'};
 return result;
}
function changeCard(row){
 if(row.version)return row;
 const c=JSON.parse(row.contextJson).retentionChange;
 if(!c)return null;
 if(row.state==='cancelled')return {version:1,status:'notice',text:'Cancelled. Retention was not changed.'};
 if(row.state!=='preview'||Date.parse(row.expiresAt)<=Date.now())return {version:1,status:'notice',text:'This retention choice expired or was already handled. Send a new command.'};
 const text=(c.mediaType==='tv'?'📺 ':'🎬 ')+c.title+'\n\n'+(c.operation==='permanent'?'Keep your requests for this title permanently, including future episodes attached to them?':`Add ${c.days} days to each currently imported eligible file’s effective expiry (or now, if later)?\nWatching cannot shorten this extension. Upcoming episodes keep their existing retention.`)+'\n\nNo media will be re-downloaded.';
 return {version:1,status:'confirmation',text,pendingId:String(row.id),choices:[{label:'Confirm',action:'confirm'},{label:'Cancel',action:'cancel'}]};
}
if(typeof module!=='undefined')module.exports={parseChange,prepareChange,planChange,changeCard};

if(!$json.version&&JSON.parse($json.contextJson||'{}').retentionChange)return [{json:changeCard($json)}];
// Pure policy functions embedded into native n8n Code nodes.
const DAY_MS=86400000;
function parseRetention(text,type) {
 if(typeof text!=='string'||!['movie','tv'].includes(type))throw new Error('Invalid retention input');
 const permanent=/\b(?:keep\s+(?:permanently|forever)|never\s+delete|do\s+not\s+delete|don't\s+delete|no\s+expiry)\b/gi;
 const timed=/\b(?:keep\s+(?:for\s+)?|retain\s+(?:for\s+)?|delete\s+after\s+|remove\s+after\s+|expire\s+(?:after|in)\s+)([0-9]+)\s+days?\b/gi;
 const forever=[...text.matchAll(permanent)], durations=[...text.matchAll(timed)];
 if(forever.length+durations.length>1)throw new Error('Use one retention instruction');
 let remainder=text.replace(permanent,'').replace(timed,'');
 if(/\b(?:keep\s+for|retain|delete|remove\s+after|expir\w*|keep\s+(?:permanently|forever|[-\d]))\b/i.test(remainder))throw new Error('Use keep for N days or keep permanently');
 const days=forever.length?null:durations.length?Number(durations[0][1]):type==='movie'?7:30;
 if(days!==null&&(!Number.isInteger(days)||days<1||days>3650))throw new Error('Retention must be 1 to 3650 days');
 return {version:2,days,explicit:!!(forever.length||durations.length)};
}
function retentionText(policy,type) {
 if(policy.days===null)return '🗃️ Keep permanently. No automatic deletion.';
 return `🗓️ Auto-delete ${policy.days} days after ${type==='tv'?'each episode imports':'import'}. Watching may shorten this to 7 days after watching; it never extends the deadline.`;
}
function effectiveExpiry(importedAt,days,watchedAt,previousDeadline,minimumExpiry) {
 if(days===null)return null;
 const imported=Date.parse(importedAt);
 if(!Number.isFinite(imported)||!Number.isInteger(days)||days<1||days>3650)throw new Error('Invalid expiry inputs');
 let deadline=imported+days*DAY_MS;
 if(watchedAt!==null&&watchedAt!==undefined){
  const watched=Date.parse(watchedAt);if(!Number.isFinite(watched))throw new Error('Invalid watch timestamp');
  deadline=Math.min(deadline,Math.max(imported,watched)+7*DAY_MS);
 }
 if(previousDeadline){const previous=Date.parse(previousDeadline);if(!Number.isFinite(previous))throw new Error('Invalid saved deadline');deadline=Math.min(deadline,previous);}
 if(minimumExpiry){const floor=Date.parse(minimumExpiry);if(!Number.isFinite(floor))throw new Error('Invalid explicit extension');deadline=Math.max(deadline,floor);}
 return new Date(deadline).toISOString();
}
function subscription(episodes,choice,now) {
 const regular=episodes.filter(e=>Number.isSafeInteger(e.id)&&e.id>0&&Number.isInteger(e.seasonNumber)&&e.seasonNumber>0);
 const historicalSeasons=[...new Set(regular.filter(e=>Number.isFinite(Date.parse(e.airDateUtc))&&Date.parse(e.airDateUtc)<=now).map(e=>e.seasonNumber))].sort((a,b)=>a-b);
 let selectedSeasons;
 if(choice==='all')selectedSeasons=[...new Set(regular.map(e=>e.seasonNumber))];
 else if(choice==='latest')selectedSeasons=[historicalSeasons.at(-1)||Math.min(...regular.map(e=>e.seasonNumber))];
 else if(/^season_[1-9][0-9]{0,3}$/.test(choice))selectedSeasons=[Number(choice.slice(7))];
 else throw new Error('Invalid subscription choice');
 if(!selectedSeasons.length||selectedSeasons.some(s=>!Number.isFinite(s)))throw new Error('No season metadata yet');
 const result={historicalSeasons,selectedSeasons,episodeIds:[]};
 result.episodeIds=regular.filter(e=>belongsToSubscription(e,result)).map(e=>String(e.id));
 return result;
}
function belongsToSubscription(e,s) {
 return Number.isSafeInteger(e.id)&&e.id>0&&Number.isInteger(e.seasonNumber)&&e.seasonNumber>0&&
  (s.selectedSeasons.includes(e.seasonNumber)||!s.historicalSeasons.includes(e.seasonNumber));
}
function fileDecision(claims,coveredIds,now) {
 if(!claims.length)return {due:false,reason:'unclaimed',expiresAt:null};
 const covered=new Set(claims.flatMap(c=>c.episodeIds||[]));
 if(coveredIds.some(id=>!covered.has(String(id))))return {due:false,reason:'unclaimed episode in shared file',expiresAt:null};
 let latest=0;
 for(const c of claims){
  if(!c.baselineCaptured||c.preexisting||c.days===null)return {due:false,reason:'protected claim',expiresAt:null};
  const expiry=effectiveExpiry(c.importedAt,c.days,c.watchedAt,c.previousDeadline,c.minimumExpiry);
  latest=Math.max(latest,Date.parse(expiry));
 }
 return {due:latest<=now,reason:latest<=now?'expired':'retained',expiresAt:new Date(latest).toISOString()};
}
function mediaSnapshot(response) {
 if(response.statusCode===404)return null;
 if(response.statusCode!==200||!Number.isSafeInteger(response.body?.id)||response.body.id<1)throw new Error('Media snapshot unavailable');
 return response.body;
}
if(typeof module!=='undefined')module.exports={parseRetention,retentionText,effectiveExpiry,subscription,belongsToSubscription,fileDecision,mediaSnapshot};

const r=$json;
if(r.version)return [{json:r}];
const notice=text=>[{json:{version:1,status:'notice',text}}];
if(!r.id)return notice('Unable to prepare that request. Please try again.');
if(r.state==='cancelled')return notice('Request cancelled. Nothing was downloaded.');
if(!['preview','scope','seasons'].includes(r.state))return notice('This request was already handled. Send a new request if needed.');
if(Date.parse(r.expiresAt)<=Date.now())return notice('This request expired. Please send it again.');
const m=JSON.parse(r.mediaJson);
const header=(r.mediaType==='movie'?'🎬 ':'📺 ')+m.title+(m.year?' ('+m.year+')':'');
const rp=JSON.parse(r.contextJson||'{}').retentionPolicy;let choices=[],text=header+(rp?'\n\n'+retentionText(rp,r.mediaType):'');if(r.mediaType==='tv'&&rp)text+='\nSelected seasons and future seasons will be monitored.';
if(r.state==='preview'){
 text+='\n\n'+String(m.overview||'No description available.').slice(0,450)+'\n\nIs this the correct '+(r.mediaType==='movie'?'movie':'series')+'?';
 choices=[{label:'Confirm',action:'confirm'},{label:'Cancel',action:'cancel'}];
}else if(r.state==='scope'){
 text+='\n\nWhich episodes would you like?\nLatest means the newest season with aired episodes. Specials are excluded; new episodes and future seasons will download automatically.';
 choices=[{label:'Latest season',action:'latest'},{label:'Choose a season',action:'choose'},{label:'All seasons',action:'all'},{label:'Cancel',action:'cancel'}];
}else{
 const seasons=[...new Set((m.seasons||[]).map(s=>s.seasonNumber).filter(s=>Number.isInteger(s)&&s>0&&s<=9999))].sort((a,b)=>a-b);
 const page=/^page_[0-9]+$/.test(r.choice||'')?Number(r.choice.slice(5)):0;
 text+='\n\nChoose a season. Aired episodes will be searched now; upcoming episodes will be monitored.';
 choices=seasons.slice(page*20,page*20+20).map(s=>({label:'Season '+s,action:'season_'+s}));
 if(page>0)choices.push({label:'Previous',action:'page_'+(page-1)});
 if((page+1)*20<seasons.length)choices.push({label:'Next',action:'page_'+(page+1)});
 choices.push({label:'Cancel',action:'cancel'});
}
const poster=(m.images||[]).find(x=>x.coverType==='poster');
const url=poster?.remoteUrl||poster?.url;
const out={version:1,status:'confirmation',text,pendingId:String(r.id),choices};
if(typeof url==='string'&&url.length<=2048&&/^https:\/\/(image\.tmdb\.org|artworks\.thetvdb\.com)\/[A-Za-z0-9_./%~-]+$/.test(url))out.posterUrl=url;
return [{json:out}];
